//! `ChunkGenerator.applyBiomeDecoration` against the real vanilla method: which placed features run, in which order, at
//! which origin and with which random state (the first `nextLong` after `setFeatureSeed`), for the biomes found in the
//! 3x3 chunks around the decorated one. Fixture: `tests/fixtures/decoration/decoration.txt`, generated by
//! `tests/oracle/DecorationOracle.java`; the placed features are recording stand-ins on both sides.

use crate::decoration_common;

use crate::decoration_common::{feature_name, fixture, generators};
use indexmap::IndexMap;
use mc_core::pos::{BlockPos, ChunkPos};
use mc_core::random::RandomSource;
use mc_game::server::level::world_gen::{GenChunk, WorldGenRegion};
use mc_game::server::packs::resource_manager::EmptyResourceManager;
use mc_game::world::level::levelgen::decoration::{
    DecorationInput, StepFeature, StepFeatureData, apply_biome_decoration_observed,
    sort_features_per_step,
};
use mc_game::world::level::levelgen::env::GenEnv;
use mc_game::world::level::levelgen::feature::Feature;
use mc_game::world::level::levelgen::gen_level::GenLevel;
use mc_game::world::level::levelgen::holder::Holder;
use mc_game::world::level::levelgen::placement::PlacedFeature;
use mc_game::world::level::levelgen::registries::{
    BLOCK_STATE_PROVIDER_REGISTRY, FEATURE_REGISTRY, GenRegistries, PLACED_FEATURE_REGISTRY,
    TypedRegistry,
};
use mc_game::world::level::levelgen::structure::check::{NoChunkScan, StructureCheck};
use mc_game::world::level::levelgen::structure::registries::{StartCache, StructureRegistries};
use mc_game::world::level::levelgen::structure::templatesystem::StructureTemplateManager;
use mc_game::world::level::levelgen::world_gen_level::WorldGenLevel;
use mc_world::chunk::{LevelHeight, ProtoChunk};
use mc_world::palette::{BiomeId, PalettedContainerFactory};
use mc_world::upgrade_data::UpgradeData;
use mc_worldgen::random_state::RandomState;
use std::collections::HashMap;
use std::sync::{Arc, Mutex};

/// The oracle's `Recording` feature: logs `name firstLong x,y,z` and places nothing.
struct Recording {
    name: String,
    log: Arc<Mutex<Vec<String>>>,
}

impl Feature for Recording {
    fn place(
        &self,
        _level: &mut dyn WorldGenLevel,
        _generator: &GenEnv,
        random: &mut dyn RandomSource,
        origin: BlockPos,
    ) -> bool {
        let first = random.next_long();
        self.log.lock().unwrap().push(format!(
            "{} {first} {},{},{}",
            self.name,
            origin.x(),
            origin.y(),
            origin.z()
        ));
        false
    }
}

fn empty_registries() -> Arc<GenRegistries> {
    Arc::new(GenRegistries {
        features: TypedRegistry::new(FEATURE_REGISTRY, IndexMap::new()),
        placed_features: TypedRegistry::new(PLACED_FEATURE_REGISTRY, IndexMap::new()),
        block_state_providers: TypedRegistry::new(BLOCK_STATE_PROVIDER_REGISTRY, IndexMap::new()),
        block_transformers: TypedRegistry::new(
            mc_game::world::item::block_transformer::BLOCK_TRANSFORMER_REGISTRY,
            IndexMap::new(),
        ),
    })
}

fn env_for(
    all: &decoration_common::Generators,
    generator: &Arc<dyn mc_worldgen::generator::ChunkGenerator>,
    registries: &Arc<GenRegistries>,
    template_manager: &Arc<StructureTemplateManager>,
    settings: &mc_worldgen::noise_settings::NoiseGeneratorSettings,
    seed: i64,
    level_height: LevelHeight,
) -> Arc<GenEnv> {
    Arc::new(GenEnv {
        dimension: mc_core::ident::Identifier::parse("minecraft:overworld").unwrap(),
        seed,
        generator: generator.clone(),
        random_state: Arc::new(RandomState::create(all.registries.clone(), seed, settings)),
        biomes: all.biomes.clone(),
        registries: registries.clone(),
        structure_template_manager: template_manager.clone(),
        structures: Arc::new(StructureRegistries::empty()),
        start_cache: StartCache::default(),
        structure_state: None,
        structure_check: StructureCheck::new(Box::new(NoChunkScan)),
        generate_structures: false,
        level_height,
    })
}

/// A feature that throws: vanilla wraps it into a `Feature placement` crash report naming the placed feature.
struct Boom;

impl Feature for Boom {
    fn place(
        &self,
        _level: &mut dyn WorldGenLevel,
        _generator: &GenEnv,
        _random: &mut dyn RandomSource,
        _origin: BlockPos,
    ) -> bool {
        panic!("boom");
    }
}

#[test]
fn a_throwing_feature_is_a_feature_placement_crash() {
    let text = fixture();
    let all = generators(&text);
    let registries = empty_registries();
    let template_manager = Arc::new(StructureTemplateManager::new(
        Arc::new(EmptyResourceManager),
        std::env::temp_dir().join("decoration-loop-golden"),
    ));
    let settings = all
        .registries
        .noise_settings(&mc_core::ident::Identifier::parse("minecraft:overworld").unwrap())
        .unwrap();
    let factory =
        PalettedContainerFactory::create(mc_world::palette::BiomeRegistry::new(all.biomes.names()))
            .unwrap();
    let level_height = LevelHeight::new(-64, 384);
    let (_, generator) = all
        .generators
        .iter()
        .find(|(n, _)| n == "overworld")
        .unwrap();
    let env = env_for(
        &all,
        generator,
        &registries,
        &template_manager,
        &settings,
        0,
        level_height,
    );
    let sorted = sort_features_per_step(generator.as_ref(), &all.biomes).unwrap();
    let features: Vec<StepFeatureData> = sorted
        .iter()
        .map(|step| {
            StepFeatureData::new(
                step.iter()
                    .map(|reference| StepFeature {
                        reference: reference.clone(),
                        feature: Arc::new(PlacedFeature {
                            feature: Holder::direct(Arc::new(Boom)),
                            placement: Vec::new(),
                        }),
                    })
                    .collect(),
            )
        })
        .collect();
    let center = ChunkPos::new(2, -5);
    let chunks = ChunkPos::range_closed(&center, 1)
        .map(|pos| {
            (
                pos.pack(),
                GenChunk::Loaned(Box::new(ProtoChunk::new(
                    pos,
                    UpgradeData::empty(),
                    level_height,
                    &factory,
                    None,
                ))),
            )
        })
        .collect();
    let mut region = WorldGenRegion::new(center, 1, 1, chunks, HashMap::new(), level_height);
    let input = DecorationInput {
        center,
        generation_height: level_height,
        biomes_in_range: vec![all.biomes.id_of_name("plains").unwrap()],
    };
    let mut level = GenLevel::new(&mut region, env.clone());
    let payload = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        apply_biome_decoration_observed(&mut level, &env, &features, &input, &mut |_| {})
    }))
    .expect_err("the feature throws");
    let report = payload
        .downcast::<mc_game::crash_report::ReportedException>()
        .expect("a ReportedException")
        .0;
    assert_eq!(report.title(), "Feature placement");
    let text = report.get_details();
    // plains lists these step-ordered; the first placed feature of the lowest step is the one that crashed
    let first = features
        .iter()
        .flat_map(|s| &s.features)
        .find(|f| {
            all.biomes
                .get(all.biomes.id_of_name("plains").unwrap())
                .generation_settings()
                .features()
                .iter()
                .flatten()
                .any(|r| *r == f.reference)
        })
        .unwrap();
    assert!(text.contains("-- Feature --"), "{text}");
    assert!(
        text.contains(&format!(
            "Description: ResourceKey[minecraft:worldgen/placed_feature / {}]",
            feature_name(&first.reference)
        )),
        "{text}"
    );
    assert!(report.exception().contains("boom"));
}

#[test]
fn apply_biome_decoration_matches_vanilla() {
    let text = fixture();
    let all = generators(&text);
    let registries = empty_registries();
    let template_manager = Arc::new(StructureTemplateManager::new(
        Arc::new(EmptyResourceManager),
        std::env::temp_dir().join("decoration-loop-golden"),
    ));
    let settings = all
        .registries
        .noise_settings(&mc_core::ident::Identifier::parse("minecraft:overworld").unwrap())
        .unwrap();
    let factory =
        PalettedContainerFactory::create(mc_world::palette::BiomeRegistry::new(all.biomes.names()))
            .unwrap();

    let sorted: HashMap<&str, Vec<Vec<mc_worldgen::biome::PlacedFeatureRef>>> = all
        .generators
        .iter()
        .map(|(name, generator)| {
            (
                name.as_str(),
                sort_features_per_step(generator.as_ref(), &all.biomes).unwrap(),
            )
        })
        .collect();

    let lines: Vec<&str> = text.lines().collect();
    let mut cases = 0;
    let mut placements = 0;
    let mut i = 0;
    while i < lines.len() {
        let Some(case) = lines[i].strip_prefix("CASE ") else {
            i += 1;
            continue;
        };
        let mut head = case.splitn(5, ' ');
        let (name, seed, cx, cz, biome_names) = (
            head.next().unwrap(),
            head.next().unwrap().parse::<i64>().unwrap(),
            head.next().unwrap().parse::<i32>().unwrap(),
            head.next().unwrap().parse::<i32>().unwrap(),
            head.next().unwrap(),
        );
        let decoration_seed: i64 = lines[i + 1]
            .strip_prefix("DECSEED ")
            .unwrap()
            .parse()
            .unwrap();
        let expected: Vec<&str> = lines[i + 2..]
            .iter()
            .take_while(|l| l.starts_with("PLACE "))
            .map(|l| &l["PLACE ".len()..])
            .collect();
        i += 2 + expected.len();

        let (_, generator) = all.generators.iter().find(|(n, _)| n == name).unwrap();
        let (min_y, height) = if name == "overworld" || name.starts_with("flat") {
            (-64, 384)
        } else {
            (0, 256)
        };
        let level_height = LevelHeight::new(min_y, height);
        let env = env_for(
            &all,
            generator,
            &registries,
            &template_manager,
            &settings,
            seed,
            level_height,
        );

        let log = Arc::new(Mutex::new(Vec::new()));
        let features: Vec<StepFeatureData> = sorted[name]
            .iter()
            .map(|step| {
                StepFeatureData::new(
                    step.iter()
                        .map(|reference| StepFeature {
                            reference: reference.clone(),
                            feature: Arc::new(PlacedFeature {
                                feature: Holder::direct(Arc::new(Recording {
                                    name: feature_name(reference),
                                    log: log.clone(),
                                })),
                                placement: Vec::new(),
                            }),
                        })
                        .collect(),
                )
            })
            .collect();

        let center = ChunkPos::new(cx, cz);
        let mut chunks = HashMap::new();
        for pos in ChunkPos::range_closed(&center, 1) {
            chunks.insert(
                pos.pack(),
                GenChunk::Loaned(Box::new(ProtoChunk::new(
                    pos,
                    UpgradeData::empty(),
                    level_height,
                    &factory,
                    None,
                ))),
            );
        }
        let mut region = WorldGenRegion::new(center, 1, 1, chunks, HashMap::new(), level_height);
        let input = DecorationInput {
            center,
            generation_height: level_height,
            biomes_in_range: biome_names
                .split(',')
                .map(|n| all.biomes.id_of_name(n).unwrap_or_else(|| panic!("{n}")))
                .collect::<Vec<BiomeId>>(),
        };
        let mut level = GenLevel::new(&mut region, env.clone());
        let mut events = Vec::new();
        apply_biome_decoration_observed(&mut level, &env, &features, &input, &mut |e| {
            events.push(e.clone())
        });

        assert!(
            events.iter().all(|e| e.decoration_seed == decoration_seed),
            "{name} seed {seed} chunk {cx},{cz}"
        );
        // the stand-ins place at the chunk's min section origin
        let got = log.lock().unwrap().clone();
        assert_eq!(
            got.len(),
            expected.len(),
            "{name} seed {seed} chunk {cx},{cz} biomes {biome_names}"
        );
        for (n, (got, want)) in got.iter().zip(&expected).enumerate() {
            assert_eq!(
                got, want,
                "{name} seed {seed} chunk {cx},{cz} biomes {biome_names} placement {n}"
            );
        }
        assert_eq!(events.len(), expected.len());
        cases += 1;
        placements += expected.len();
    }
    assert_eq!(cases, 292);
    assert!(placements > 5000, "{placements}");
}
